function fstr(f){ if(!f) return 'null'; if(f.type==='SOLID') return 'SOLID:'+JSON.stringify(f.color); if(f.type==='IMAGE') return 'IMAGE:'+f.imageHash; return f.type; }
function fillsOf(n){ if(!('fills' in n)) return '-'; return Array.isArray(n.fills)? n.fills.map(fstr).join('|') : 'mixed'; }
function info(n){
  const o = { id:n.id, name:n.name, type:n.type, w:Math.round(n.width*100)/100, h:Math.round(n.height*100)/100, fills: fillsOf(n) };
  if('strokes' in n && Array.isArray(n.strokes)) o.strokes = n.strokes.map(fstr).join('|') + ' w:' + (n.strokeWeight!==undefined?n.strokeWeight:'-');
  if('cornerRadius' in n) o.radius = n.cornerRadius;
  if('effects' in n && Array.isArray(n.effects) && n.effects.length) o.fx = n.effects.map(e=>e.type).join(',');
  if('layoutMode' in n) o.al = n.layoutMode;
  if(n.type==='TEXT'){ try{ o.font = n.fontName.family+' / '+n.fontName.style; }catch(e){ o.font='?'; } o.size=n.fontSize; o.chars=(n.characters||'').slice(0,80); o.ls=JSON.stringify(n.letterSpacing); o.lh=JSON.stringify(n.lineHeight); }
  if('children' in n && n.children) o.kids = n.children.map(c=>info(c));
  return o;
}
