const get = id => figma.getNodeByIdAsync(id);
const home = await get('13:83');
const prop = await get('16:271');
const out={ wired: [], failed: [] };

const nav = (node, dest, mode) => {
  node.reactions = [{ trigger:{type:'ON_CLICK'}, actions:[{type:'NODE', destinationId:dest, navigation:mode||'NAVIGATE', transition:null}] }];
};

const heroBtn = home.findAll(n=>n.type==='INSTANCE').find(i=>i.findAll(t=>t.type==='TEXT').some(t=>t.characters==='See all listings'));
try{ nav(heroBtn,'16:271'); out.wired.push('hero:'+heroBtn.id); }catch(e){ out.failed.push('hero:'+e.message); }
for(const cid of ['14:108','14:129','14:150','14:172','14:193','14:214']){
  const c = await get(cid);
  try{ nav(c,'16:271'); out.wired.push('card:'+cid); }catch(e){ out.failed.push('card:'+cid+':'+e.message); }
}

const header = prop.findOne(n=>n.name==='Header');
const logo = header && header.findOne(n=>n.name==='Logo');
try{ nav(logo,'13:83'); out.wired.push('logo:'+logo.id); }catch(e){ out.failed.push('logo:'+e.message); }

const simRow = prop.findOne(n=>n.name==='Similar').findOne(n=>n.name==='Row');
for(const c of simRow.children){
  try{
    nav(c,'16:271');
    out.wired.push('sim:'+c.id);
  }catch(e){
    try{
      nav(c,'16:271','SWAP');
      out.wired.push('sim-swap:'+c.id);
    }catch(e2){ out.failed.push('sim:'+c.id+':'+e2.message); }
  }
}
return JSON.stringify(out);

